package com.singtel.customerservice;import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import com.singtel.platformcommon.DomainError;import java.util.*;
@RestController @RequestMapping("/api/v1/customers") @PreAuthorize("hasAnyRole('MANAGER','APPROVER','ANALYST','ADMIN')")public class CustomerController{private final CustomerRepository repo;public CustomerController(CustomerRepository r){repo=r;}@GetMapping public List<Customer> list(@RequestParam(defaultValue="0")int page,@RequestParam(defaultValue="100")int size){if(page<0||size<1||size>100)throw new IllegalArgumentException();return repo.findAll(org.springframework.data.domain.PageRequest.of(page,size)).getContent();}@GetMapping("/{id}")public Customer get(@PathVariable String id){return repo.findById(id).orElseThrow(DomainError::missing);}}
